package com.optarena;

// Memoizes squares behind an LRU cache with capacity 2.
public class MemoService {
    private final LruCache<Integer, Integer> cache = new LruCache<>(2);

    public int square(int n) {
        Integer cached = cache.get(n);
        if (cached != null) {
            return cached;
        }
        int value = n * n;
        cache.put(n, value);
        return value;
    }

    public int cacheSize() {
        return cache.size();
    }
}

