package com.optarena;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

import org.junit.jupiter.api.Test;

class LruCacheHiddenTest {

    @Test
    void evictsLeastRecentlyUsed() {
        LruCache<String, Integer> cache = new LruCache<>(2);
        cache.put("a", 1);
        cache.put("b", 2);
        // touch "a" so "b" becomes least-recently-used
        assertEquals(1, cache.get("a"));
        cache.put("c", 3); // should evict "b", not "a"
        assertNull(cache.get("b"), "b should have been evicted");
        assertEquals(1, cache.get("a"), "a should still be present");
        assertEquals(3, cache.get("c"), "c should be present");
        assertEquals(2, cache.size());
    }

    @Test
    void memoServiceRespectsCapacity() {
        MemoService memo = new MemoService();
        assertEquals(9, memo.square(3));
        assertEquals(16, memo.square(4));
        assertEquals(2, memo.cacheSize());
        memo.square(5); // third distinct key must evict, not grow
        assertEquals(2, memo.cacheSize());
    }
}

